-- Drafts only. No slot and no publish time: the owner reviews each text.
INSERT INTO posts(text,alternative,category,status,topic,reason,generated,evidence_id,hypothesis,sources)
SELECT p.text,p.text,p.category,'draft',p.topic,p.reason,true,s.id,p.hypothesis,
 CASE WHEN s.url IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(s.url) END
FROM (VALUES
 ('Я Ілля, засновник Mimiao. Роблю CRM для шкіл і допомагаю розібратися з нею особисто.

Можна почати з однієї групи: налаштувати заняття, провести перший урок і перевірити облік. Допоможу в листуванні.

Спробувати без картки протягом 14 днів можна за посиланням у профілі.', 'founder', 'Закреплённый пост · bio', 'Проверить назначение ссылки профиля и согласовать текст. Поддержка подтверждена владельцем; trial в знаниях продукта.', 'transition', 'Основатель помогает новым школам'),
 ('Що найбільше стримує вас від зміни CRM у школі: перенести історію оплат, заново навчити команду чи перевірити, чи нова система взагалі підходить?

Хочу зрозуміти, з чого має починатися моя допомога при переході.', 'founder', 'Переход · transition-01', 'Гипотеза из обсуждения перехода keyCRM. Следующий сигнал: конкретное препятствие от владельца школы. Это вопрос, не заявление о частоте проблемы.', 'transition', 'Переход: спрашивают детали, а не ставят лайки'),
 ('Якщо придивляєтесь до Mimiao, можна почати з одного робочого сценарію й однієї групи.

Напишіть, що хочете перевірити насамперед. Допоможу розібратися, чи підходить система під ваш процес.', 'product', 'Переход · transition-02', 'Помощь подтверждена владельцем. Следующий сигнал: запрос подходящей школы и согласие проверить рабочий сценарий. Полный перенос данных не обещан.', 'transition', 'Основатель помогает новым школам'),
 ('Коли обираєте CRM для школи, що перевіряєте першим: роботу із заявками чи облік занять та оплат?

У розмовах про вибір систем бачу обидва запити. Цікаво, який із них зараз важливіший саме для вашої школи.', 'founder', 'Учёт · accounting-01', 'Основание: изученная ветка выбора CRM. Следующий сигнал: конкретный критерий от владельца школы. Не сравниваем текущие функции конкурентов по старой ветке.', 'accounting', 'Школы выбирают между внутренним учётом и продажами')
) AS p(text,category,topic,reason,hypothesis,source_title)
JOIN growth_sources s ON s.title=p.source_title;

