INSERT INTO posts(text,alternative,category,status,topic,reason,generated,hypothesis)
VALUES ('Один урок може стати тестом CRM для школи.

Створіть заняття, проведіть його й перевірте, чи зрозуміло вам, що змінилося в обліку учня та викладача. Таке завдання можна перевірити на своєму процесі.', '', 'product','draft','Учёт · accounting-02','До согласования подготовить реальный скриншот на обозначенных демонстрационных данных, проверить сценарий и добавить подтверждённый материал типа «демонстрация». Это предложение проверки, не клиентский кейс.',true,'accounting');
